+   * ```typescript
+   * const agent = new PromaAgent({ apiKey, workingDirectory: process.cwd() });
+   * for await (const event of agent.chat("Hello!")) {
+   *   if (event.type === 'text_delta') {
+   *     process.stdout.write(event.text);
+   *   }
+   * }
+   * ```
+   */
