+      workingDirectory: this.config.workingDirectory,
+      useFullToolSet: this.config.useFullToolSet,
+      mcpServers: this.config.mcpServers,
+    });
+
+    // 确定权限模式
+    const hasCanUseTool = !!this.config.canUseTool;
