+	}
+	if path == "" {
+		path = "/hook"
+	}
+	if !strings.HasPrefix(path, "/") {
+		path = "/" + path
+	}
+	return &WebhookServer{
+		port:    port,
+		token:   token,
+		path:    path,
+		engines: make(map[string]*Engine),
+	}
+}
+
+func (ws *WebhookServer) RegisterEngine(name string, e *Engine) {
+	ws.mu.Lock()
+	defer ws.mu.Unlock()
+	ws.engines[name] = e
+}
+
