+		slog.Info("webhook: server started", "addr", addr, "path", ws.path)
+		if err := ws.server.ListenAndServe(); err != nil && err != http.ErrServerClosed {
+			slog.Error("webhook: server error", "error", err)
+		}
+	}()
+}
+
+func (ws *WebhookServer) Stop() {
+	if ws.server != nil {
