+
+// --- Types ---
+
+export interface ChannelAction {
+  type: 'send' | 'ask' | 'delegate';
+  channel: string;
+  content: string;
+  to?: string;
+  askId?: string;
+  /** Character index in the accumulated text where this marker starts */
+  startIndex: number;
+}
+
+export interface PendingAsk {
+  askId: string;
+  panelId: string;
+  channel: string;
+  channelId: string;
+  question: string;
+  to?: string;
+  sentAt: number;
+  reply?: string;
+  repliedAt?: number;
+}
+
+export interface QueuedChannelMessage {
+  channelId: string;
+  channelName: string;
+  content: string;
+  sender?: string;
+  timestamp: number;
