+  clearPanel(panelId: string): void {
+    this._processedMarkerPositions.delete(panelId);
+    this._pendingAsks.delete(panelId);
+    this._queuedMessages.delete(panelId);
+  }
+
+  /**
+   * Dispose all resources.
+   */
