+    for (const [key, contact] of this._trackedContacts) {
+      // Expire stale tracked contacts
+      if (now - contact.sentAt > TRACKED_CONTACT_TTL_MS) {
+        this._trackedContacts.delete(key);
+        continue;
+      }
