+    this.name = 'N8nRateLimitError';
+  }
+}
+
+export class N8nServerError extends N8nApiError {
+  constructor(message = 'Internal server error', statusCode = 500) {
+    super(message, statusCode, 'SERVER_ERROR');
+    this.name = 'N8nServerError';
+  }
